def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = [c for c in counts if c != background]
    if len(colors) != 1:
        raise ValueError("expected one foreground color")
    foreground = colors[0]
    out = [row[:] for row in grid]
    # Join aligned foreground marks with the secondary color across background gaps.
    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] == foreground]
        for left, right in zip(marks, marks[1:]):
            for c in range(left + 1, right):
                if grid[r][c] == background:
                    out[r][c] = 2
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] == foreground]
        for top, bottom in zip(marks, marks[1:]):
            for r in range(top + 1, bottom):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out
